import{_ as t,o as a,c as o,a4 as d}from"./chunks/framework.CzJ_HCFe.js";const p=JSON.parse('{"title":"Bhumi Puja / house-foundation source profile","description":"","frontmatter":{},"headers":[],"relativePath":"reference/13-bhumi-puja-foundation-profile.md","filePath":"reference/13-bhumi-puja-foundation-profile.md","lastUpdated":1788530310000}'),r={name:"reference/13-bhumi-puja-foundation-profile.md"};function i(n,e,s,c,h,l){return a(),o("div",null,[...e[0]||(e[0]=[d('<h1 id="bhumi-puja-house-foundation-source-profile" tabindex="-1">Bhumi Puja / house-foundation source profile <a class="header-anchor" href="#bhumi-puja-house-foundation-source-profile" aria-label="Permalink to &quot;Bhumi Puja / house-foundation source profile&quot;">​</a></h1><h2 id="authority-and-scope" tabindex="-1">Authority and scope <a class="header-anchor" href="#authority-and-scope" aria-label="Permalink to &quot;Authority and scope&quot;">​</a></h2><p>The configured profile is for laying the foundation of a house. It is based on B. V. Raman, <em>Muhurtha (Electional Astrology)</em>, Chapter XII, “House Building” / “Laying the Foundation,” printed page 50 (PDF page 54):</p><p><a href="https://www.panchanga.lv/wp-content/uploads/2020/06/Muhurta_Raman.pdf" target="_blank" rel="noreferrer">https://www.panchanga.lv/wp-content/uploads/2020/06/Muhurta_Raman.pdf</a></p><p>Raman is a modern synthesis and secondary authority, not a primary scripture. The product label “Bhumi Puja / Foundation laying” is broader than Raman&#39;s heading; this profile elects the foundation-laying moment and does not claim to prescribe the complete Puja paddhati.</p><h2 id="rule-to-code-crosswalk" tabindex="-1">Rule-to-code crosswalk <a class="header-anchor" href="#rule-to-code-crosswalk" aria-label="Permalink to &quot;Rule-to-code crosswalk&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Source statement</th><th>Locator</th><th>Implementation</th><th>Treatment</th></tr></thead><tbody><tr><td>Chaitra, Vaishakha, Shravana, Kartika and Magha are best; the other seven named months are rejected</td><td>p. 50 (PDF 54)</td><td><code>allowed_maasams</code></td><td>Only the five stated months are admitted. <code>Adhika</code>/<code>Nija</code> prefixes are normalized before comparison.</td></tr><tr><td>Surya should occupy a fixed Rasi or at least a movable Rasi; common Rasis are rejected</td><td>p. 50 (PDF 54)</td><td><code>allowed_solar_classes</code></td><td>Fixed and movable solar-sign classes are admitted; common signs reject the day.</td></tr><tr><td>Eight Nakshatras are best, seven ordinary/middling, and the remaining twelve rejected</td><td>p. 50 (PDF 54)</td><td><code>allowed_nakshatras</code>; <code>prefer_nakshatras</code></td><td>Best and middling groups survive; only the best group receives the disclosed +1 distinction.</td></tr><tr><td>All odd Tithis except the 9th; among even Tithis, 2nd, 6th and 10th</td><td>p. 50 (PDF 54)</td><td><code>allowed_tithi_numbers</code></td><td>The active slot-time Tithi number must be one of 1, 2, 3, 5, 6, 7, 10, 11, 13 or 15.</td></tr><tr><td>Monday, Wednesday, Thursday and Friday are best; waning-Moon Monday rejected</td><td>p. 50 (PDF 54)</td><td><code>allowed_varas</code>; <code>avoid_vara_paksha</code></td><td>Only the four stated best weekdays are automated; Krishna-Paksha Monday is then explicitly rejected.</td></tr><tr><td>Fixed rising Rasi is best; movable rejected; common possible only with strong benefics</td><td>p. 50 (PDF 54)</td><td><code>required_lagna_class: Sthira</code></td><td>Conservative automation requires a fixed Lagna because the exceptional benefic-strength condition is not fully computed.</td></tr><tr><td>Malefics in 3/6/11, benefics in Kendras/Trikonas; 8th vacant and without malefic aspect</td><td>p. 50 (PDF 54)</td><td><code>manual_checks</code></td><td>Disclosed for practitioner review; the finder does not claim full election-chart validation.</td></tr><tr><td>First foundation stone at the north-eastern corner after Puja</td><td>p. 50 (PDF 54)</td><td><code>manual_checks</code></td><td>Ritual/site instruction only; never inferred from astronomical data.</td></tr></tbody></table><h2 id="product-contract-and-limitations" tabindex="-1">Product contract and limitations <a class="header-anchor" href="#product-contract-and-limitations" aria-label="Permalink to &quot;Product contract and limitations&quot;">​</a></h2><p>Python, MCP, and browser consume one activity-rule contract. Day-level source failures are explained; active slot-time Tithi, Nakshatra and Lagna gates are applied after day admission. Every result repeats the manual checks, and MCP exposes the stable <code>muhurta.bhumi_puja.foundation</code> provenance identifier.</p><p>The existing samskara-yoga exclusion, hard inauspicious windows, Panchaka, Tarabalam, Chandrabalam, choghadiya contribution and relative tiers are shared project rules. This Chapter XII citation does not establish them. A surviving candidate is therefore a screened foundation-laying time, not a complete Vastu or ritual certification.</p>',10)])])}const m=t(r,[["render",i]]);export{p as __pageData,m as default};
